/* ============================================
   RedRoom Fitness — Design System
   Dark, bold, premium HIIT brand
   ============================================ */

/* ── CSS Variables (OKLCH palette) ── */
:root {
  /* Brand colors */
  --brand-red: oklch(58% 0.24 25);
  --brand-red-hover: oklch(52% 0.26 25);
  --brand-red-glow: oklch(58% 0.24 25 / 0.35);

  /* Backgrounds */
  --bg-primary: oklch(8% 0.01 280);
  --bg-secondary: oklch(12% 0.01 280);
  --bg-tertiary: oklch(16% 0.015 280);
  --bg-card: oklch(14% 0.012 280);

  /* Text */
  --text-primary: oklch(98% 0.005 280);
  --text-secondary: oklch(75% 0.02 280);
  --text-muted: oklch(55% 0.02 280);

  /* Borders */
  --border-subtle: oklch(22% 0.015 280);
  --border-focus: oklch(58% 0.24 25);

  /* Typography */
  --font-display: 'Oswald', 'Bebas Neue', Impact, sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Arial, sans-serif;

  /* Spacing scale */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;

  /* Radii */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;

  /* Shadows */
  --shadow-sm: 0 1px 2px oklch(0% 0 0 / 0.3);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.4);
  --shadow-lg: 0 8px 30px oklch(0% 0 0 / 0.5);
  --shadow-red: 0 0 24px var(--brand-red-glow);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  /* Layout */
  --container-max: 1280px;
  --nav-height: 64px;
}

/* ── Reset & Base ── */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* ── Typography ── */
.heading-xl {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 700;
  line-height: 1.05;
  text-transform: uppercase;
  letter-spacing: -0.02em;
}

.heading-lg {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4.5vw, 3.5rem);
  font-weight: 700;
  line-height: 1.1;
  text-transform: uppercase;
  letter-spacing: -0.01em;
}

.heading-md {
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 600;
  line-height: 1.15;
  text-transform: uppercase;
}

.heading-sm {
  font-family: var(--font-display);
  font-size: clamp(1.125rem, 2vw, 1.5rem);
  font-weight: 600;
  line-height: 1.2;
  text-transform: uppercase;
}

.body-lg {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--text-secondary);
}

.body-md {
  font-size: 1rem;
  line-height: 1.65;
  color: var(--text-secondary);
}

.body-sm {
  font-size: 0.875rem;
  line-height: 1.5;
  color: var(--text-muted);
}

.label {
  font-family: var(--font-display);
  font-size: 0.75rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--brand-red);
}

/* ── Layout Utilities ── */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin-inline: auto;
  padding-inline: var(--space-6);
}

.section {
  padding-block: var(--space-24);
}

.section-sm {
  padding-block: var(--space-16);
}

.flex {
  display: flex;
}

.flex-col {
  flex-direction: column;
}

.items-center {
  align-items: center;
}

.justify-center {
  justify-content: center;
}

.justify-between {
  justify-content: space-between;
}

.gap-2 { gap: var(--space-2); }
.gap-4 { gap: var(--space-4); }
.gap-6 { gap: var(--space-6); }
.gap-8 { gap: var(--space-8); }

.grid {
  display: grid;
}

.text-center { text-align: center; }

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-family: var(--font-display);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  border-radius: var(--radius-sm);
  transition: all var(--transition-base);
  white-space: nowrap;
}

.btn-primary {
  background-color: var(--brand-red);
  color: var(--text-primary);
  box-shadow: var(--shadow-sm);
}

.btn-primary:hover {
  background-color: var(--brand-red-hover);
  box-shadow: var(--shadow-red);
  transform: translateY(-1px);
}

.btn-secondary {
  background-color: transparent;
  color: var(--text-primary);
  border: 1.5px solid var(--border-subtle);
}

.btn-secondary:hover {
  border-color: var(--brand-red);
  color: var(--brand-red);
}

.btn-lg {
  padding: var(--space-4) var(--space-8);
  font-size: 1rem;
}

/* ── Cards ── */
.card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--space-6);
  transition: all var(--transition-base);
}

.card:hover {
  border-color: var(--border-focus);
  box-shadow: var(--shadow-md);
}

/* ── Forms ── */
.input {
  width: 100%;
  padding: var(--space-3) var(--space-4);
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-family: var(--font-body);
  font-size: 1rem;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.input::placeholder {
  color: var(--text-muted);
}

.input:focus {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px var(--brand-red-glow);
}

.form-message {
  font-size: 0.875rem;
  margin-top: var(--space-2);
}

.form-message.success {
  color: oklch(70% 0.15 145);
}

.form-message.error {
  color: var(--brand-red);
}

/* ── Navigation ── */
.topbar {
  background-color: var(--brand-red);
  color: var(--text-primary);
  text-align: center;
  padding: var(--space-2) var(--space-4);
  font-size: 0.8125rem;
  font-weight: 500;
}

.topbar a {
  text-decoration: underline;
  text-underline-offset: 2px;
  margin-left: var(--space-2);
}

.navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: oklch(8% 0.01 280 / 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-subtle);
  height: var(--nav-height);
}

.navbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-primary);
}

.logo span {
  color: var(--brand-red);
}

.nav-links {
  display: none;
  align-items: center;
  gap: var(--space-6);
}

.nav-links a {
  font-family: var(--font-display);
  font-size: 0.8125rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
  position: relative;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
}

.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--brand-red);
  transition: width var(--transition-base);
}

.nav-links a:hover::after,
.nav-links a.active::after {
  width: 100%;
}

.nav-cta {
  display: none;
}

.mobile-menu-btn {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
}

.mobile-menu-btn span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--text-primary);
  transition: all var(--transition-base);
}

.mobile-nav {
  display: none;
  position: fixed;
  inset: var(--nav-height) 0 0 0;
  background-color: var(--bg-primary);
  z-index: 99;
  padding: var(--space-8);
  flex-direction: column;
  gap: var(--space-6);
}

.mobile-nav.open {
  display: flex;
}

.mobile-nav a {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.mobile-nav a:hover,
.mobile-nav a.active {
  color: var(--brand-red);
}

/* ── Hero ── */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    oklch(8% 0.01 280 / 0.3) 0%,
    oklch(8% 0.01 280 / 0.85) 100%
  ),
  radial-gradient(ellipse at 50% 0%, oklch(58% 0.24 25 / 0.15) 0%, transparent 60%);
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  text-align: center;
  max-width: 900px;
  padding: var(--space-8);
}

.hero .label {
  margin-bottom: var(--space-4);
  display: inline-block;
}

.hero .heading-xl {
  margin-bottom: var(--space-6);
}

.hero .body-lg {
  margin-bottom: var(--space-8);
  max-width: 600px;
  margin-inline: auto;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-4);
  justify-content: center;
}

/* ── Section Header ── */
.section-header {
  text-align: center;
  max-width: 700px;
  margin-inline: auto;
  margin-bottom: var(--space-16);
}

.section-header .label {
  margin-bottom: var(--space-3);
  display: inline-block;
}

.section-header .heading-lg {
  margin-bottom: var(--space-4);
}

/* ── Two Column Layout ── */
.two-col {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-12);
  align-items: center;
}

.two-col.reverse .col-text {
  order: 2;
}

.two-col.reverse .col-visual {
  order: 1;
}

.col-visual {
  position: relative;
}

.col-visual img {
  border-radius: var(--radius-md);
  width: 100%;
  height: 100%;
  object-fit: cover;
  min-height: 300px;
}

.col-visual::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: var(--radius-md);
  box-shadow: inset 0 0 60px oklch(0% 0 0 / 0.4);
  pointer-events: none;
}

/* ── Feature Cards Grid ── */
.features-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-6);
}

.feature-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.feature-card:hover {
  border-color: var(--brand-red);
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.feature-card .icon {
  width: 48px;
  height: 48px;
  background-color: var(--brand-red);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-4);
  color: var(--text-primary);
}

.feature-card .heading-sm {
  margin-bottom: var(--space-3);
}

/* ── Toggle Component ── */
.toggle-group {
  display: inline-flex;
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  overflow: hidden;
  margin-bottom: var(--space-8);
}

.toggle-btn {
  padding: var(--space-3) var(--space-6);
  font-family: var(--font-display);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.toggle-btn.active {
  background-color: var(--brand-red);
  color: var(--text-primary);
}

.toggle-btn:not(.active):hover {
  color: var(--text-primary);
}

.toggle-panel {
  display: none;
  animation: fadeIn 300ms ease;
}

.toggle-panel.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ── Table ── */
.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 1rem;
}

.data-table thead {
  border-bottom: 2px solid var(--brand-red);
}

.data-table th {
  font-family: var(--font-display);
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  text-align: left;
  padding: var(--space-4) var(--space-4);
  color: var(--text-muted);
}

.data-table td {
  padding: var(--space-4) var(--space-4);
  border-bottom: 1px solid var(--border-subtle);
  color: var(--text-secondary);
}

.data-table tbody tr {
  transition: background-color var(--transition-fast);
}

.data-table tbody tr:hover {
  background-color: var(--bg-tertiary);
}

.data-table td:first-child {
  font-weight: 600;
  color: var(--text-primary);
}

/* ── Filter Controls ── */
.filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-bottom: var(--space-8);
  justify-content: center;
}

.filter-pill {
  padding: var(--space-2) var(--space-4);
  font-family: var(--font-display);
  font-size: 0.8125rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  transition: all var(--transition-fast);
  cursor: pointer;
}

.filter-pill:hover {
  border-color: var(--brand-red);
  color: var(--text-primary);
}

.filter-pill.active {
  background-color: var(--brand-red);
  border-color: var(--brand-red);
  color: var(--text-primary);
}

/* ── Instructor Grid ── */
.instructor-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-6);
}

.instructor-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: all var(--transition-base);
}

.instructor-card:hover {
  border-color: var(--brand-red);
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.instructor-photo {
  width: 100%;
  aspect-ratio: 1;
  background: linear-gradient(135deg, var(--bg-tertiary), var(--bg-secondary));
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.instructor-photo::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 50%, oklch(0% 0 0 / 0.6) 100%);
}

.instructor-photo svg {
  width: 64px;
  height: 64px;
  color: var(--text-muted);
  opacity: 0.5;
}

.instructor-info {
  padding: var(--space-5);
}

.instructor-info .name {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 600;
  text-transform: uppercase;
  margin-bottom: var(--space-1);
}

.instructor-info .location {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: var(--space-4);
}

.instructor-info .btn {
  width: 100%;
}

/* ── Accordion ── */
.accordion {
  max-width: 800px;
  margin-inline: auto;
}

.accordion-item {
  border-bottom: 1px solid var(--border-subtle);
}

.accordion-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-5) 0;
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: 600;
  text-transform: uppercase;
  text-align: left;
  color: var(--text-primary);
  transition: color var(--transition-fast);
}

.accordion-header:hover {
  color: var(--brand-red);
}

.accordion-icon {
  width: 24px;
  height: 24px;
  position: relative;
  flex-shrink: 0;
  margin-left: var(--space-4);
}

.accordion-icon::before,
.accordion-icon::after {
  content: '';
  position: absolute;
  background-color: currentColor;
  transition: transform var(--transition-base);
}

.accordion-icon::before {
  width: 12px;
  height: 2px;
  top: 11px;
  left: 6px;
}

.accordion-icon::after {
  width: 2px;
  height: 12px;
  top: 6px;
  left: 11px;
}

.accordion-item.open .accordion-icon::after {
  transform: rotate(90deg);
  opacity: 0;
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
}

.accordion-item.open .accordion-body {
  max-height: 500px;
  padding-bottom: var(--space-5);
}

.accordion-body p {
  color: var(--text-secondary);
  line-height: 1.7;
}

/* ── Carousel ── */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16 / 9;
  background: linear-gradient(135deg, var(--bg-tertiary), var(--bg-secondary));
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.carousel-slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.carousel-slide .slide-caption {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: var(--space-8) var(--space-6) var(--space-6);
  background: linear-gradient(transparent, oklch(0% 0 0 / 0.8));
}

.carousel-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  background-color: oklch(8% 0.01 280 / 0.7);
  backdrop-filter: blur(4px);
  border: 1px solid var(--border-subtle);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-primary);
  transition: all var(--transition-fast);
  z-index: 2;
}

.carousel-nav:hover {
  background-color: var(--brand-red);
  border-color: var(--brand-red);
}

.carousel-nav.prev { left: var(--space-4); }
.carousel-nav.next { right: var(--space-4); }

.carousel-dots {
  display: flex;
  gap: var(--space-2);
  justify-content: center;
  margin-top: var(--space-4);
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--border-subtle);
  transition: all var(--transition-fast);
}

.carousel-dot.active {
  background-color: var(--brand-red);
  transform: scale(1.2);
}

/* ── CTA Band ── */
.cta-band {
  background: linear-gradient(
    135deg,
    var(--bg-secondary) 0%,
    oklch(12% 0.02 25) 100%
  );
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
  text-align: center;
  padding-block: var(--space-20);
}

.cta-band .heading-lg {
  margin-bottom: var(--space-6);
}

/* ── Newsletter ── */
.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  max-width: 480px;
  margin-inline: auto;
}

.newsletter-form .input {
  flex: 1;
}

/* ── Footer ── */
.footer {
  background-color: var(--bg-secondary);
  border-top: 1px solid var(--border-subtle);
  padding-block: var(--space-16) var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-10);
  margin-bottom: var(--space-12);
}

